// === Tab: mySketch ===
let xs;
let rs;
let ss;
let zs;

let n = 10000;

let speed = 0.001;

function setup() {  
  createCanvas(windowWidth, windowHeight, WEBGL);

  noStroke();
  background(0);
  // fill(255);
	fill(255, 255, 0);
  text("Loading. Please wait.", width/2, height/2);
}

let tilt = 0.2;
let mx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
let my = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));

let first = 0;
function draw() {
  if (first==0) {
    first = 1;
  } else if (first ==1) {
    xs = new Array(n);
    rs = new Array(n);
    ss = new Array(n);
    zs = new Array(n);
    let m = 2;
    for (i = 0; i<n; i++) {
      xs[i] = sq(random(1.4))+random(0.05);
      rs[i] = ((sqrt(sin(random(PI/2))))+int(random)(m)+random(0.01))/m*TWO_PI
        -(9*sqrt(xs[i]));
      ss[i]=  random(1, 4);
      zs[i] = sq((random(0.1)))*(random(1)>.5?-1:1)*xs[i]*10;
    }
    first = 2;
  } else {

    mx+=((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))-mx)/4;
    my+=((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-my)/4;
    background(0);

    translate(width/2, height/2);
    fill(255, 150);

    rotate(tilt);

    for (i = 0; i<n; i++) {
      pushMatrix();

      let r = rs[i]-float(mx)/1000;
      let x = xs[i];

      let close = 1+sin(r-0.5)*sqrt(x);


      translate(0, zs[i]*width);

      scale(1/pow(2, 1-close));

      ellipse(x*width*(cos(r)+sin(r)), 
        x*width*(sin(r)-cos(r))*map(my, 0, height, -0.3, 0.3), ss[i], ss[i]);

      rs[i]+=(x/(x+1)+0*close/4)*speed/xs[i]*(20/frameRate);

      popMatrix();
    }
  }
}

